package cn.zhuatech.churnai.controller; import cn.zhuatech.churnai.common.ApiResponse; import cn.zhuatech.churnai.dto.ChurnAiDto.*; import cn.zhuatech.churnai.service.ChurnAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final ChurnAiService service;public OperationsAdminController(ChurnAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
